inline void TSellCreatureWindow::SetWidgetOff(short id)
{
    BroadcastMessage(MESSAGE_WIDGET, 5, id, 0x1000);
}

inline void TSellCreatureWindow::SetWidgetDisabled(short id)
{
    BroadcastMessage(MESSAGE_WIDGET, 6, id, 0x1006);
}

